use anyhow :: { Context , Result } ; use std :: fs ; use std :: path :: { Path , PathBuf } ; use std :: io :: { BufRead , BufReader } ; use log :: info ; fn find_files_recursively (base : & Path , pattern : & str) -> Result < Vec < PathBuf > > { let mut files = Vec :: new () ; if ! base . exists () { return Ok (files) ; } for entry in fs :: read_dir (base) ? { let entry = entry ? ; let path = entry . path () ; if path . is_dir () { let mut sub_files = find_files_recursively (& path , pattern) ? ; files . append (& mut sub_files) ; } else if path . file_name () . and_then (| n | n . to_str ()) == Some (pattern) { files . push (path) ; } } Ok (files) }